-- Baseline for a NEW database only. Never apply blindly to an existing installation.
BEGIN;
CREATE TABLE schema_version (version integer PRIMARY KEY, description varchar(255) NOT NULL);
CREATE SEQUENCE hibernate_sequence START WITH 1 INCREMENT BY 1;
CREATE TABLE Course (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(255));
CREATE TABLE Degree (id bigint PRIMARY KEY, name varchar(255));
CREATE TABLE Expertise (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(255));
CREATE TABLE Project_Type (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(255));
CREATE TABLE Professor (id bigint PRIMARY KEY, name varchar(255), email varchar(255), picture varchar(255), degree_id bigint REFERENCES Degree);
CREATE TABLE Project (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, title varchar(255), type_id bigint REFERENCES Project_Type, professor_id bigint REFERENCES Professor);
CREATE TABLE Student (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(255), ra varchar(255), email varchar(255), picture varchar(255), course_id bigint REFERENCES Course, project_id bigint REFERENCES Project);
CREATE TABLE Committee (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, day integer, start_time time(6), end_time time(6), project_id bigint UNIQUE REFERENCES Project);
CREATE TABLE Schedule (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, day integer, start_time time(6), end_time time(6), course_id bigint REFERENCES Course, professor_id bigint REFERENCES Professor);
CREATE TABLE Committee_Professor (committees_id bigint NOT NULL REFERENCES Committee, professors_id bigint NOT NULL REFERENCES Professor);
CREATE TABLE Professor_Expertise (professors_id bigint NOT NULL REFERENCES Professor, expertises_id bigint NOT NULL REFERENCES Expertise);
CREATE TABLE Project_Expertise (projects_id bigint NOT NULL REFERENCES Project, expertises_id bigint NOT NULL REFERENCES Expertise);
INSERT INTO schema_version VALUES (1, 'Legacy JPA model, explicit baseline');
COMMIT;
